export const categoryList = (db) => collection(db, "category");

export const categoryDoc = (id: string, db: any) => doc(db, "category", id);
export const itemDoc = (id: string, db: any) => doc(db, "Items", id);
export const itemList = (db) => collection(db, "Items");

// Filters a collection to one user's docs when they share a pooled Firebase
// project (scopeUserId set). Dedicated-project users pass `undefined` and get
// the collection back untouched, since their data is already isolated by database.
export const scopedQuery = (
  colRef: CollectionReference,
  scopeUserId?: string
): CollectionReference | Query =>
  scopeUserId ? query(colRef, where("userId", "==", scopeUserId)) : colRef;

// The pooled project's *owner* (e.g. manish) reads that same collection
// unfiltered by `scopedQuery` (no where clause), which would otherwise also
// return other pooled users' tagged docs. Apply this afterward for every
// user so docs explicitly tagged with someone else's userId are dropped —
// a no-op for dedicated-project users and already-filtered pooled users,
// since none of their docs are tagged with a foreign userId to begin with.
export const filterOwnDocs = <T,>(docs: T[], userId: string): T[] =>
  docs.filter((d: any) => !d?.userId || d.userId === userId);

export type TModes = "ADD" | "EDIT";

export interface IItemNCategoryFormProps {
  mode: TModes;
  id?: string;
  handleMode?: (newMode: TModes, id: string) => any;
}
