import { Box } from "@mui/material";

import CategoryList from "./CategoryList";
import { useEffect, useState } from "react";
import { getDocs } from "firebase/firestore";
import { useDataStateContext } from "../context/DataStateContext";
import { categoryList, filterOwnDocs, scopedQuery, TModes } from "../Utils/Utils";
import CategoryForm from "./CategoryForm";
import { useFireBase } from "../../context/FirebaseConfigContext";
import { getDataScopeUserId, getFirebaseServices } from "../../Firebase/config";

const Category = () => {
  const { dispatch, state } = useDataStateContext();
  const [refreshToken, setRefreshToken] = useState(state?.refreshToken);
  const [editId, setEditId] = useState("");
  const [mode, setMode] = useState<TModes>("ADD");

  const { state: firebaseState } = useFireBase();
  const db = getFirebaseServices(firebaseState.userId).db;
  const scopeUserId = getDataScopeUserId(firebaseState.userId);

  const refresh = () => {
    setRefreshToken((prev) => prev + 1);
  };

  const handleEditMode = (newMode: TModes, id: string) => {
    newMode && setMode(newMode);
    id && setEditId(id);
    scrollToElement();
  };

  const scrollToElement = () => {
    window.scrollTo({
      top: 0,
      left: 0,
      behavior: "smooth",
    });
  };

  useEffect(() => {
    const getCategory = async () => {
      try {
        const data = await getDocs(scopedQuery(categoryList(db), scopeUserId));
        const categoryData: any = data?.docs?.map((doc) => {
          return { ...doc.data(), id: doc.id };
        });

        dispatch({
          type: "addCategory",
          payload: filterOwnDocs(categoryData || [], firebaseState.userId),
        });
      } catch (e) {
        console.log(e);
        dispatch({ type: "addCategory", payload: [] });
      }
    };
    getCategory();
  }, [dispatch, refreshToken, scopeUserId]);

  return (
    <div>
      <CategoryForm
        refresh={refresh}
        mode={mode}
        id={mode === "EDIT" ? editId : ""}
        handleMode={handleEditMode}
      />
      <CategoryList refresh={refresh} handleMode={handleEditMode} />
    </div>
  );
};

export default Category;
